# Custom Script Extension bootstrap shared by ALL Windows VMs across scenarios
# (Workgroup Driver/SUT; Domain DC/Driver/SUT; Cluster DC/Storage/Nodes/Driver).
# The Bicep modules load this file
# with loadTextContent(), substitute the __TOKENS__, base64 it into the
# extension's encrypted protectedSettings, and the commandToExecute decodes and
# runs it on the VM.
#
# Tokens injected at compile/deploy time:
#   __SCENARIO__       workgroup | domain | cluster
#   __ROLE__           dc | storage | node01 | node02 | driver | sut
#   __PACKAGE_NAME__   Workgroup-Package | Domain-Package | Cluster-Package
#   __DEPLOY_SCRIPT__  Role-specific Deploy-*.ps1
#   __PACKAGE_URL__    URL of the package zip
#   __PACKAGE_HOST__   host part of the URL (DNS readiness probe)
#   __PASSWORD_B64__   base64 admin password for Set-ConfigCredential.ps1
#   __CONFIG_JSON_B64__ optional complete Config.json override for one-click deployments
#
# When the extension pre-downloads the package via fileUris, the zip is found in
# the CWD and used directly. Otherwise this script waits for DNS and downloads it
# itself -- needed by domain members whose only DNS server is the DC, which may
# still be promoting when the extension fires.

$ErrorActionPreference = 'Stop'
Set-ExecutionPolicy -ExecutionPolicy Unrestricted -Force
Start-Transcript -Path 'C:\__SCENARIO__-__ROLE__-setup.log' -Append
$stagingRoot = 'C:\__PACKAGE_NAME__.staging.' + $PID

function Complete-Bootstrap {
    param([int]$ExitCode)

    Remove-Item -LiteralPath $stagingRoot -Recurse -Force -ErrorAction SilentlyContinue
    Stop-Transcript -ErrorAction SilentlyContinue
    Remove-Item -LiteralPath $PSCommandPath -Force -ErrorAction SilentlyContinue
    exit $ExitCode
}

trap {
    Write-Output "Bootstrap failed: $($_.Exception.Message)"
    Complete-Bootstrap -ExitCode 1
}

Write-Output 'Starting __SCENARIO__ __ROLE__ setup...'
New-Item -ItemType Directory -Path 'C:\__PACKAGE_NAME__' -Force | Out-Null

# Package already present? This supports an extension retry that retained a
# completed download. Package URLs remain only in protectedSettings; public
# fileUris settings are intentionally not used because ARM persists them.
$zipFile = Get-ChildItem -Path . -Filter *.zip -ErrorAction SilentlyContinue | Select-Object -First 1

if (-not $zipFile) {
    Write-Output 'Waiting for DNS resolution of __PACKAGE_HOST__ (DNS may still be coming up)...'
    $dns = $false
    for ($i = 0; $i -lt 60; $i++) {
        try {
            Resolve-DnsName -Name '__PACKAGE_HOST__' -ErrorAction Stop | Out-Null
            $dns = $true
            break
        } catch {
            Start-Sleep -Seconds 30
        }
    }
    if (-not $dns) {
        Write-Output 'DNS resolution of __PACKAGE_HOST__ failed after retries'
        Complete-Bootstrap -ExitCode 1
    }

    $zipPath = 'C:\__PACKAGE_NAME__.zip'
    $dl = $false
    for ($i = 0; $i -lt 10; $i++) {
        try {
            Start-BitsTransfer -Source '__PACKAGE_URL__' -Destination $zipPath -ErrorAction Stop
            $dl = $true
            break
        } catch {
            Write-Output "BITS download attempt failed: $($_.Exception.Message)"
            try {
                Add-Type -AssemblyName System.Net.Http
                $handler = New-Object System.Net.Http.HttpClientHandler
                $handler.AllowAutoRedirect = $true
                $client = New-Object System.Net.Http.HttpClient($handler)
                $client.Timeout = [TimeSpan]::FromMinutes(15)
                try {
                    $response = $client.GetAsync('__PACKAGE_URL__').GetAwaiter().GetResult()
                    $response.EnsureSuccessStatusCode()
                    $inputStream = $response.Content.ReadAsStreamAsync().GetAwaiter().GetResult()
                    $outputStream = [System.IO.File]::Open(
                        $zipPath,
                        [System.IO.FileMode]::Create,
                        [System.IO.FileAccess]::Write,
                        [System.IO.FileShare]::None
                    )
                    try {
                        $inputStream.CopyTo($outputStream)
                    }
                    finally {
                        $outputStream.Dispose()
                        $inputStream.Dispose()
                    }
                    if ((Get-Item -LiteralPath $zipPath).Length -le 0) {
                        throw 'Downloaded package is empty.'
                    }
                    $dl = $true
                    break
                }
                finally {
                    $client.Dispose()
                    $handler.Dispose()
                }
            }
            catch {
                Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue
                Write-Output "HTTP download attempt failed: $($_.Exception.Message)"
                Start-Sleep -Seconds 30
            }
        }
    }
    if (-not $dl) {
        Write-Output 'Package download failed'
        Complete-Bootstrap -ExitCode 1
    }
    $zipFile = Get-Item $zipPath
}

Add-Type -AssemblyName System.IO.Compression.FileSystem
$archive = [System.IO.Compression.ZipFile]::OpenRead($zipFile.FullName)
try {
    if ($archive.Entries.Count -eq 0) {
        throw 'Package ZIP contains no entries.'
    }
}
finally {
    $archive.Dispose()
}

Write-Output "Extracting $($zipFile.Name)..."
Remove-Item -LiteralPath $stagingRoot -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Path $stagingRoot -Force | Out-Null
Expand-Archive -Path $zipFile.FullName -DestinationPath $stagingRoot -Force
Write-Output 'Package extracted to validation staging'

$contractsPath = Join-Path $stagingRoot 'DSC\Scripts\Package-Contracts.ps1'
if (Test-Path -LiteralPath $contractsPath -PathType Leaf) {
    . $contractsPath
    Test-DscPackageManifest -PackageRoot $stagingRoot `
        -ExpectedScenario '__SCENARIO__' -ThrowOnFailure | Out-Null
    Write-Output 'Package manifest and content hashes verified'
}
elseif ('__SCENARIO__' -eq 'cluster') {
    throw 'Package-Contracts.ps1 is missing from the Cluster package.'
}
else {
    # Migration compatibility for already-published Domain/Workgroup v1 assets.
    # Newly built packages always carry the manifest and take the strict path.
    foreach ($legacyRequiredPath in @(
        (Join-Path $stagingRoot 'Config.json'),
        (Join-Path $stagingRoot 'DSC\__DEPLOY_SCRIPT__'),
        (Join-Path $stagingRoot 'DSC\Scripts\InstallMSIAndTools.ps1')
    )) {
        $legacyItem = Get-Item -LiteralPath $legacyRequiredPath -ErrorAction SilentlyContinue
        if ($null -eq $legacyItem -or $legacyItem.Length -le 0) {
            throw "Legacy package required file is missing or empty: $legacyRequiredPath"
        }
    }
    Write-Output 'Legacy Domain/Workgroup package accepted with required-content checks'
}

Copy-Item -Path (Join-Path $stagingRoot '*') `
    -Destination 'C:\__PACKAGE_NAME__' -Recurse -Force
Remove-Item -LiteralPath $stagingRoot -Recurse -Force
Remove-Item $zipFile.FullName -Force
Write-Output 'Validated package overlaid successfully'

$configJsonBase64 = '__CONFIG_JSON_B64__'
if (-not [string]::IsNullOrWhiteSpace($configJsonBase64) -and
    $configJsonBase64 -ne '__CONFIG_JSON_B64__') {
    $configJson = [System.Text.Encoding]::UTF8.GetString(
        [System.Convert]::FromBase64String($configJsonBase64)
    )
    $null = $configJson | ConvertFrom-Json -ErrorAction Stop
    Set-Content -LiteralPath 'C:\__PACKAGE_NAME__\Config.json' `
        -Value $configJson -Encoding UTF8 -NoNewline -Force
    Set-Content -LiteralPath 'C:\__PACKAGE_NAME__\DSC\Scripts\Config.json' `
        -Value $configJson -Encoding UTF8 -NoNewline -Force
    Write-Output 'One-click Config.json override applied'
}

if (Test-Path 'C:\__PACKAGE_NAME__\DSC\Scripts\Set-ConfigCredential.ps1') {
    Write-Output 'Injecting credential into Config.json...'
    & 'C:\__PACKAGE_NAME__\DSC\Scripts\Set-ConfigCredential.ps1' -PasswordBase64 '__PASSWORD_B64__'
}

function Protect-PackageFile {
    param([string]$Path)

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return }
    & icacls.exe $Path '/inheritance:r' `
        '/grant:r' '*S-1-5-18:F' '*S-1-5-32-544:F' | Out-Null
    if ($LASTEXITCODE -ne 0) {
        throw "Failed to restrict ACLs on '$Path' (icacls exit $LASTEXITCODE)."
    }
}

foreach ($protectedPath in @(
    'C:\__PACKAGE_NAME__\Config.json',
    'C:\__PACKAGE_NAME__\DSC\Scripts\Config.json',
    'C:\__PACKAGE_NAME__\ResultsUpload.json'
)) {
    Protect-PackageFile -Path $protectedPath
}

$deployScript = 'C:\__PACKAGE_NAME__\DSC\__DEPLOY_SCRIPT__'
if (-not (Test-Path -LiteralPath $deployScript -PathType Leaf)) {
    throw '__DEPLOY_SCRIPT__ is missing from the package.'
}

Write-Output 'Starting __DEPLOY_SCRIPT__ in a checked child PowerShell process...'
$deployArguments = @(
    '-NoProfile',
    '-NonInteractive',
    '-ExecutionPolicy', 'Unrestricted',
    '-File', $deployScript,
    '-WorkingPath', 'C:\__PACKAGE_NAME__'
)
$deployProcess = Start-Process -FilePath 'powershell.exe' `
    -ArgumentList $deployArguments `
    -WorkingDirectory 'C:\__PACKAGE_NAME__\DSC' `
    -PassThru
if (-not $deployProcess.WaitForExit(14400000)) {
    Stop-Process -Id $deployProcess.Id -Force -ErrorAction SilentlyContinue
    throw '__DEPLOY_SCRIPT__ exceeded the four-hour bootstrap deadline.'
}
if ($deployProcess.ExitCode -ne 0) {
    throw "__DEPLOY_SCRIPT__ failed with exit code $($deployProcess.ExitCode)."
}

Write-Output '__SCENARIO__ __ROLE__ extension setup completed'
Complete-Bootstrap -ExitCode 0

